require __DIR__.'/lib.php';require_login();$lock=null;$id=(int)($_POST['run_id']??0);try{ir_admin();if($_SERVER['REQUEST_METHOD']!=='POST')throw new Exception('Use the Fresh Start form.');verify_csrf();$lock=inventory_write_lock();$action=$_POST['action']??'';if($action==='prepare'){$id=ir_prepare($_POST['reason']??'');flash('Backup integrity verified. Download a copy and review the reset scope. No inventory changed.');}elseif($action==='apply'){ir_apply($id,$_POST['digest']??'',$_POST['confirmation']??'',$_POST['current_password']??'',!empty($_POST['review_ack']),!empty($_POST['download_ack']));ir_session_guard();flash('Inventory reset complete. Stocks are zero, existing SKU and setup are preserved, and Beginning Balance is unlocked.');}elseif($action==='cancel'){ir_cancel($id);flash('Reset preview cancelled. No inventory changed.');}else throw new Exception('Unknown reset action.');}catch(Throwable $ex){flash(safe_error_message($ex),'danger');}finally{if($lock)inventory_write_unlock($lock);}header('Location: index.php?page=fresh_start'.($id?'&run='.$id:''));exit;
